Решение. 
Для решения этой задачи считаем строку из файла. Инициализируем строковую переменную s1 со значением ABCDEFGHIJKLMNOPQRSTUVWXYZ. Посимвольно перебирая строку из файла, каждый раз встречая букву A, будем вставлять в строку s1 символ, идущий после буквы A в считанной строке, таким образом, чтобы в строке s1 соответствующие символы стояли рядом друг с другом (например, если из файла была считана строка ABAB, строка s1 после выполнения алгоритма будет выглядеть так: ABBBCDEFGHIJKLMNOPQRSTUVWXYZ. После этого посчитаем длину самой длинной цепочки символов и таким образом получим ответ.
Приведём решение данной задачи на языке Pascal.
var 
len, max, count: longint;
s, s1: string;
maxC: char;
f: text;
begin
 assign(f,'C:\24.txt');
 reset(f);
 readln(f, s);
 len := length(s);
 s1 := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
 for i:integer := 1 to len do begin
 if ((s[i] = 'A') and (i <> len)) then
 s1 := s1.Substring(0, s1.LastIndexOf(s[i+1])) + s[i+1] + s1.Substring(s1.LastIndexOf(s[i+1]));
 end;
 len := length(s1);
 max := 1;
 count := 0;
 for i:integer := 1 to len-1 do begin
 if (s1[i] = s1[i+1]) then count := count + 1
 else count := 0;
 if count > max then begin
 max := count;
 maxC := s1[i];
 end;
 end;
 writeln(maxC);
end.
